CustomCss:
body{letter-spacing:.15px}
h2{padding-bottom:8px;border-bottom:1px solid var(--b)}
.form,.sc,.ig,table{border-radius:12px}
.form,.sc{box-shadow:0 1px 2px rgba(40,42,54,.06)}
.form:hover{border-color:var(--a);box-shadow:0 3px 14px rgba(189,147,249,.14)}
.ni{border-radius:10px;transition:background .15s ease,color .15s ease}
.ni:hover{background:var(--hover)}
.ni.active{background:rgba(189,147,249,.14);color:var(--a);font-weight:600}
button.bp,button.bd,button.bw,button.bsm{border-radius:9px;font-weight:600;transition:transform .1s ease}
button.bp:hover,button.bd:hover,button.bw:hover{transform:translateY(-1px)}
input,select,textarea{border-radius:9px}
input:focus,select:focus,textarea:focus{box-shadow:0 0 0 3px rgba(189,147,249,.22)}
.pnl.active{animation:fadeIn .25s ease}
@keyframes fadeIn{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}
